--
-- Name: update_campaign_amount(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_campaign_amount() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Update the current_amount in fundraising_campaigns
    UPDATE public.fundraising_campaigns 
    SET current_amount = (
        SELECT COALESCE(SUM(amount), 0) 
        FROM public.fundraising_donations 
        WHERE campaign_id = COALESCE(NEW.campaign_id, OLD.campaign_id)
    )
    WHERE id = COALESCE(NEW.campaign_id, OLD.campaign_id);
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


