--
-- Name: update_comments_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_comments_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE posts SET comments_count = comments_count + 1 WHERE id = NEW.post_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE posts SET comments_count = comments_count - 1 WHERE id = OLD.post_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION public.update_comments_count() OWNER TO postgres;

--
-- Name: update_course_enrollment_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_course_enrollment_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE public.skill_build_courses c
     SET current_enrollments = (
       SELECT COUNT(*) FROM public.skill_build_enrollments e WHERE e.course_id = c.id
     )
   WHERE c.id = COALESCE(NEW.course_id, OLD.course_id);
  RETURN NULL;
END;
$$;


