--
-- Name: update_skill_build_enrollments_updated_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_skill_build_enrollments_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = NOW();
  NEW.last_accessed = NOW();
  IF NEW.progress = 100 AND (OLD.progress IS NULL OR OLD.progress < 100) THEN
    NEW.completion_date = NOW();
    NEW.status = 'completed';
  END IF;
  RETURN NEW;
END;
$$;


