   FROM public.user_profiles up
  WHERE ((up.id = (auth.uid())::text) AND (up.role = 'faculty'::text) AND (assignments.branch = ANY (up.assigned_branches)) AND (assignments.semester = ANY (up.assigned_semesters)))))));


--
-- Name: fee_records Faculty view branch+semester students' fees; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Faculty view branch+semester students' fees" ON public.fee_records FOR SELECT USING ((EXISTS ( SELECT 1
   FROM (public.user_profiles fac
     JOIN public.user_profiles stu ON ((stu.student_id = fee_records.student_id)))
  WHERE ((fac.id = (auth.uid())::text) AND (fac.role = 'faculty'::text) AND (stu.branch = fac.branch) AND (COALESCE((NULLIF(regexp_replace(stu.semester, '\D'::text, ''::text, 'g'::text), ''::text))::integer, '-1'::integer) = COALESCE((NULLIF(regexp_replace(fee_records.semester, '\D'::text, ''::text, 'g'::text), ''::text))::integer, '-1'::integer))))));


--
-- Name: admin_settings Only admins can access admin_settings; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Only admins can access admin_settings" ON public.admin_settings USING (((EXISTS ( SELECT 1
   FROM public.user_profiles
  WHERE ((user_profiles.id = (auth.uid())::text) AND (user_profiles.role = 'admin'::text)))) OR ((((current_setting('request.jwt.claims'::text, true))::jsonb ->> 'email'::text) IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM public.user_profiles
  WHERE ((user_profiles.email = ((current_setting('request.jwt.claims'::text, true))::jsonb ->> 'email'::text)) AND (user_profiles.role = 'admin'::text))))))) WITH CHECK (((EXISTS ( SELECT 1
   FROM public.user_profiles
  WHERE ((user_profiles.id = (auth.uid())::text) AND (user_profiles.role = 'admin'::text)))) OR ((((current_setting('request.jwt.claims'::text, true))::jsonb ->> 'email'::text) IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM public.user_profiles
  WHERE ((user_profiles.email = ((current_setting('request.jwt.claims'::text, true))::jsonb ->> 'email'::text)) AND (user_profiles.role = 'admin'::text)))))));


