   FROM public.fundraising_campaigns fc
  WHERE ((fc.id = student_fundraising_status.campaign_id) AND (fc.status = 'active'::text) AND (EXISTS ( SELECT 1
           FROM public.user_profiles up
          WHERE ((up.id = (auth.uid())::text) AND (up.role = 'student'::text) AND (up.branch = ANY (fc.target_branches)) AND (up.semester = ANY (fc.target_semesters))))))))));


