-- Name: assignments Students can view assignments for their branch and semester; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Students can view assignments for their branch and semester" ON public.assignments FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.user_profiles up
  WHERE ((up.id = (auth.uid())::text) AND (up.role = 'student'::text) AND (up.is_approved = true) AND (up.branch = assignments.branch) AND (up.semester = assignments.semester)))));


--
-- Name: attendance_records Students can view own attendance; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Students can view own attendance" ON public.attendance_records FOR SELECT USING (((auth.uid())::text = student_uid));


--
-- Name: fundraising_campaigns Students can view relevant campaigns; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Students can view relevant campaigns" ON public.fundraising_campaigns FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.user_profiles up
  WHERE ((up.id = (auth.uid())::text) AND (up.role = 'student'::text) AND (up.branch = ANY (fundraising_campaigns.target_branches)) AND (up.semester = ANY (fundraising_campaigns.target_semesters))))));


--
-- Name: study_materials Students can view their branch semester materials; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Students can view their branch semester materials" ON public.study_materials FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.user_profiles
  WHERE ((user_profiles.id = (auth.uid())::text) AND (user_profiles.role = ANY (ARRAY['student'::text, 'alumni'::text, 'pending'::text])) AND (user_profiles.branch = study_materials.branch) AND (user_profiles.semester = study_materials.semester)))));


--
-- Name: student_fundraising_status Students can view their own status; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Students can view their own status" ON public.student_fundraising_status FOR SELECT USING (((auth.uid())::text = student_uid));


--
-- Name: fee_records Students view own fees; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Students view own fees" ON public.fee_records FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.user_profiles p
  WHERE ((p.id = (auth.uid())::text) AND (fee_records.student_id = p.student_id)))));


--
-- Name: user_preferences Users can insert own preferences; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can insert own preferences" ON public.user_preferences FOR INSERT WITH CHECK ((auth.uid() = user_id));


--
-- Name: user_profiles Users can insert their own profile; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can insert their own profile" ON public.user_profiles FOR INSERT WITH CHECK (((auth.uid())::text = id));


