-- Name: user_profiles Users can update their own profile; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can update their own profile" ON public.user_profiles FOR UPDATE USING (((auth.uid())::text = id));


--
-- Name: user_preferences Users can view own preferences; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can view own preferences" ON public.user_preferences FOR SELECT USING ((auth.uid() = user_id));


--
-- Name: fee_records Users can view their own fee records (metadata id); Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Users can view their own fee records (metadata id)" ON public.fee_records FOR SELECT USING ((((auth.jwt() -> 'user_metadata'::text) ->> 'id'::text) = student_id));


