-- Name: objects Anyone can view chat files; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Anyone can view chat files" ON storage.objects FOR SELECT USING ((bucket_id = 'chat-attachments'::text));


--
-- Name: objects Authenticated users can delete QR codes; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Authenticated users can delete QR codes" ON storage.objects FOR DELETE USING (((bucket_id = 'qr-codes'::text) AND (auth.role() = 'authenticated'::text)));


--
-- Name: objects Authenticated users can update QR codes; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Authenticated users can update QR codes" ON storage.objects FOR UPDATE USING (((bucket_id = 'qr-codes'::text) AND (auth.role() = 'authenticated'::text)));


--
-- Name: objects Authenticated users can upload QR codes; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Authenticated users can upload QR codes" ON storage.objects FOR INSERT WITH CHECK (((bucket_id = 'qr-codes'::text) AND (auth.role() = 'authenticated'::text)));


--
-- Name: objects Faculty can upload/download attachments for assignments; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Faculty can upload/download attachments for assignments" ON storage.objects USING (((bucket_id = 'assignments'::text) AND (EXISTS ( SELECT 1
   FROM public.user_profiles up
  WHERE ((up.id = (auth.uid())::text) AND (up.role = 'faculty'::text))))));


--
-- Name: objects Public can view QR codes; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Public can view QR codes" ON storage.objects FOR SELECT USING ((bucket_id = 'qr-codes'::text));


--
-- Name: objects Students can download attachments for viewable assignments; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Students can download attachments for viewable assignments" ON storage.objects FOR SELECT USING (((bucket_id = 'assignments'::text) AND (EXISTS ( SELECT 1
   FROM public.assignments a
  WHERE ((a.id = (storage.foldername(objects.name))[1]) AND (EXISTS ( SELECT 1
           FROM public.user_profiles up
          WHERE ((up.id = (auth.uid())::text) AND (up.role = 'student'::text) AND (up.is_approved = true) AND (up.branch = a.branch) AND (up.semester = a.semester)))))))));


--
-- Name: objects Users can delete their own files; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Users can delete their own files" ON storage.objects FOR DELETE USING (((bucket_id = 'chat-attachments'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));


--
-- Name: objects Users can upload chat files; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY "Users can upload chat files" ON storage.objects FOR INSERT WITH CHECK (((bucket_id = 'chat-attachments'::text) AND (auth.role() = 'authenticated'::text)));


